//! 🧰️ Dev-only support of the font crate family tests: authored font bytes and funded physical close with heap witnesses.
use semio_framework_test_fixtures::fixture_path;
use semio_framework_value::{retirement::{RetireOwned,controlled::ControlledRetirement},retained_clone::{RetainedCloneGrant,RetainedCloneStep}};
/// 🔤️ Reads one shipped font asset outline by its `🖼️assets/🔤️fonts` family path.
pub fn bytes(font:&str)->Vec<u8>{let path=fixture_path!("../../../../../../..").join("🖼️assets/🔤️fonts").join(font).join("🔤️outline.ttf");std::fs::read(path).unwrap()}
/// 🧹️ Closes one owner with single-item grants and returns the physically released bytes.
pub fn close<T:RetireOwned>(value:T)->usize{close_with_items(value,1)}
/// 🧮️ Closes one owner with `items`-item grants, proving every step against the heap witness, and returns the released bytes.
pub fn close_with_items<T:RetireOwned>(value:T,items:usize)->usize{let mut owner=ControlledRetirement::new(value).unwrap_or_else(|(error,_)|panic!("{error}"));let mut released=0;for _ in 0..if items>1{10000000}else{2000000}{if owner.terminal_is_empty(){break;}let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(if copy>0{copy}else{release}).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()};let(zero,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert!(!physical.overflowed);assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(matches!(zero,RetainedCloneStep::Progress(p)if p==Default::default()));let(step,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(grant).unwrap());let(RetainedCloneStep::Progress(receipt)|RetainedCloneStep::Complete(receipt))=step;assert!(receipt.fits(grant));assert!(!physical.overflowed);assert_eq!(physical.requested_bytes,receipt.retained_capacity_bytes);assert_eq!(physical.released_bytes,receipt.released_bytes);released+=physical.released_bytes;}assert!(owner.terminal_is_empty());let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!(physical.released_bytes,0);released}
